(()=>{'use strict';let saved=new Set();try{const value=JSON.parse(localStorage.getItem('pgg-saved')||'[]');if(Array.isArray(value))saved=new Set(value)}catch{}const finder=document.querySelector('#gift-finder'),cards=[...(finder?.querySelectorAll('.product')||[])],filters=[...document.querySelectorAll('[data-filter]')],search=document.querySelector('#site-search'),params=new URLSearchParams(location.search);if(search)search.value=params.get('q')||'';const count=document.querySelector('#result-count'),empty=document.querySelector('#empty'),status=document.querySelector('#save-status');function filter(){const vals=Object.fromEntries(filters.map(x=>[x.dataset.filter,x.value]));const terms=(search?.value||'').trim().toLowerCase().split(/\s+/).filter(Boolean);let n=0;cards.forEach(c=>{const ok=(!vals.recipient||c.dataset.recipient.split(' ').includes(vals.recipient))&&(!vals.budget||(Number(c.dataset.price)>0&&Number(c.dataset.price)<=Number(vals.budget)))&&(!vals.type||(vals.type==='saved'?saved.has(c.dataset.id):c.dataset.type===vals.type))&&terms.every(q=>c.dataset.search.includes(q));c.hidden=!ok;if(ok)n++});if(count)count.textContent=`${n} ${n===1?'gift idea':'gift ideas'}`;if(empty)empty.hidden=n>0}function sync(){document.querySelectorAll('.save').forEach(b=>{const on=saved.has(b.dataset.id);b.setAttribute('aria-pressed',String(on));b.textContent=on?'♥':'♡';b.setAttribute('aria-label',`${on?'Unsave':'Save'} ${b.dataset.name}`)});document.querySelectorAll('[data-saved-count]').forEach(e=>e.textContent=String(saved.size))}document.querySelectorAll('.save').forEach(b=>b.addEventListener('click',()=>{const on=saved.has(b.dataset.id);on?saved.delete(b.dataset.id):saved.add(b.dataset.id);try{localStorage.setItem('pgg-saved',JSON.stringify([...saved]));if(status)status.textContent=on?'Removed from saved gifts.':'Saved on this browser.'}catch{if(status)status.textContent='Saved for this visit; browser storage is unavailable.'}sync();filter()}));filters.forEach(f=>f.addEventListener('change',filter));document.querySelector('#reset')?.addEventListener('click',()=>{filters.forEach(f=>f.value='');if(search)search.value='';filter()});if(finder){document.querySelector('.search')?.addEventListener('submit',e=>{e.preventDefault();filter();finder.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});history.replaceState(null,'',search.value?'/?q='+encodeURIComponent(search.value)+'#gift-finder':'/#gift-finder')});document.querySelector('#sort')?.addEventListener('change',e=>{const mode=e.target.value;const sorted=[...cards].sort((a,b)=>mode==='low'?(Number(a.dataset.price)||Infinity)-(Number(b.dataset.price)||Infinity):mode==='high'?(Number(b.dataset.price)||-1)-(Number(a.dataset.price)||-1):mode==='name'?a.querySelector('h3').textContent.localeCompare(b.querySelector('h3').textContent):cards.indexOf(a)-cards.indexOf(b));const grid=finder.querySelector('.grid');sorted.forEach(c=>grid.append(c))});if(params.get('saved'))document.querySelector('[data-filter=type]').value='saved';filter()}sync();const carousel=document.querySelector('.carousel');if(carousel){const slides=[...carousel.querySelectorAll('[data-slide]')],dots=[...carousel.querySelectorAll('[data-slide-to]')],pause=carousel.querySelector('[data-slide-pause]'),announcement=carousel.querySelector('[data-slide-status]');let current=0,paused=matchMedia('(prefers-reduced-motion:reduce)').matches,hover=false;function render(index,announce=false){current=(index+slides.length)%slides.length;slides.forEach((s,i)=>s.hidden=i!==current);dots.forEach((d,i)=>d.setAttribute('aria-current',String(i===current)));if(announce)announcement.textContent=`Slide ${current+1} of ${slides.length}`;}function pauseUI(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow')}carousel.querySelector('[data-slide-prev]').addEventListener('click',()=>{paused=true;pauseUI();render(current-1,true)});carousel.querySelector('[data-slide-next]').addEventListener('click',()=>{paused=true;pauseUI();render(current+1,true)});dots.forEach(d=>d.addEventListener('click',()=>{paused=true;pauseUI();render(Number(d.dataset.slideTo),true)}));pause.addEventListener('click',()=>{paused=!paused;pauseUI()});carousel.addEventListener('mouseenter',()=>hover=true);carousel.addEventListener('mouseleave',()=>hover=false);carousel.addEventListener('focusin',()=>{paused=true;pauseUI()});carousel.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();paused=true;pauseUI();render(current+(e.key==='ArrowRight'?1:-1),true)}});setInterval(()=>{if(!paused&&!hover&&!document.hidden)render(current+1)},8000);pauseUI()}})();
